// EP2C5F256C8 scan core for the GDEMU 6.0 FPGA (EP2C5-compatible die).
//
// Hand-written; the port wrapper scan.v is generated by
// tools/pinfind/mk_scan.py. Address map: docs/research/ep2c5-scan.md.
//
// The MCU reads 16-bit words by address on A1..A8 (addr[7:0] = A8..A1)
// with NCS3 and NRD low. D0..D15 are driven ONLY while NCS3 and NRD are
// both low (combinational output enable); the MCU never drives them.
// Clear and arm are reads of reserved addresses (0xF0..0xF4), latched on
// the rising edge of NRD while NCS3 is low, so no write path exists.
//
// Clocks: each of the 8 dedicated clock balls clocks its own counters.
// clk[5] = H16 (v5.5 CLK_48_MHz, MCU PA21 / PCK0) is the reference for the
// gated window and the G1 observation (2-flop synchronisers). Nothing here
// needs a clock to answer a read: the constants, walking words and raw
// levels are combinational from the pins.
module scan_core #(
    parameter [15:0] WIN_LOG2 = 16'd22  // window = 2^22 H16 cycles (87.4 ms at 48 MHz)
) (
    input  wire [141:0] raw,   // every input ball, pad order (ep2c5_scan.csv)
    input  wire [7:0]   clk,   // H1 H2 J1 J2 H15 H16 J15 J16
    input  wire [32:0]  dc,    // v5.5 DC_* balls, mk_scan.DC_ORDER
    input  wire [7:0]   addr,  // MCU A8..A1
    input  wire         ncs,   // MCU NCS3 (R8), active low
    input  wire         nrd,   // MCU NRD (M12), active low
    output reg  [15:0]  d_out,
    output wire         d_oe
);
    assign d_oe = ~ncs & ~nrd;

    // ------------------------------------------------ command latch (NRD) --
    // clr: high from the end of a read of 0xF0 to the end of the next read
    // of any other address. It is a register output, so it is glitch-free,
    // and it clears every other register asynchronously (no clock needed).
    reg clr = 1'b0;
    reg arm_w = 1'b0;   // window armed (0xF1), off by 0xF0
    reg arm_g = 1'b0;   // G1 observation on (0xF2), off by 0xF3 / 0xF0
    always @(posedge nrd) begin
        if (!ncs) begin
            clr <= (addr == 8'hF0);
            case (addr)
                8'hF0: begin arm_w <= 1'b0; arm_g <= 1'b0; end
                8'hF1: arm_w <= 1'b1;
                8'hF2: arm_g <= 1'b1;
                8'hF3: arm_g <= 1'b0;
                default: ;
            endcase
        end
    end

    wire ref_clk = clk[5];

    // ------------------------------------------- H16 domain: arm, window --
    reg [1:0] aw_s, ag_s;
    always @(posedge ref_clk or posedge clr) begin
        if (clr) begin
            aw_s <= 2'b00;
            ag_s <= 2'b00;
        end else begin
            aw_s <= {aw_s[0], arm_w};
            ag_s <= {ag_s[0], arm_g};
        end
    end
    wire g_en = ag_s[1];

    reg win_run, win_done;
    reg [WIN_LOG2-1:0] win_cnt;
    always @(posedge ref_clk or posedge clr) begin
        if (clr) begin
            win_run <= 1'b0;
            win_done <= 1'b0;
            win_cnt <= {WIN_LOG2{1'b0}};
        end else if (win_run) begin
            win_cnt <= win_cnt + 1'b1;
            if (&win_cnt) begin
                win_run <= 1'b0;
                win_done <= 1'b1;
            end
        end else if (aw_s[1] && !win_done) begin
            win_run <= 1'b1;
        end
    end

    // -------------------------------------- per-clock-ball counters (x8) --
    // fc: free-running, every rising edge since the last clear (32 bit).
    // wc: rising edges while the H16 window (synchronised into the ball's
    //     own domain with 2 flops) is open (24 bit). For H16 itself this is
    //     exactly 2^WIN_LOG2.
    wire [255:0] fcv;
    wire [191:0] wcv;
    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : ck
            reg [31:0] fc;
            reg [23:0] wc;
            reg [1:0]  es;
            always @(posedge clk[i] or posedge clr) begin
                if (clr) begin
                    fc <= 32'd0;
                    wc <= 24'd0;
                    es <= 2'b00;
                end else begin
                    fc <= fc + 1'b1;
                    es <= {es[0], win_run};
                    if (es[1]) wc <= wc + 1'b1;
                end
            end
            assign fcv[32*i +: 32] = fc;
            assign wcv[24*i +: 24] = wc;
        end
    endgenerate

    // ------------------------------------------------ G1 observation (H16) --
    // Every input ball, 2-flop synchronised: seen0 / seen1 while armed.
    reg [141:0] s1, s2;
    always @(posedge ref_clk) begin
        s1 <= raw;
        s2 <= s1;
    end
    reg [141:0] seen0, seen1;
    always @(posedge ref_clk or posedge clr) begin
        if (clr) begin
            seen0 <= {142{1'b0}};
            seen1 <= {142{1'b0}};
        end else if (g_en) begin
            seen0 <= seen0 | ~s2;
            seen1 <= seen1 | s2;
        end
    end

    // DC_* balls: synchronised (c2) and one sample older (c3).
    reg [32:0] c1, c2, c3;
    always @(posedge ref_clk) begin
        c1 <= dc;
        c2 <= c1;
        c3 <= c2;
    end

    // Saturating 8-bit toggle counters, one per DC_* ball.
    wire [263:0] togv;
    genvar j;
    generate
        for (j = 0; j < 33; j = j + 1) begin : tg
            reg [7:0] t;
            always @(posedge ref_clk or posedge clr) begin
                if (clr)
                    t <= 8'd0;
                else if (g_en && (c2[j] ^ c3[j]) && t != 8'hFF)
                    t <= t + 1'b1;
            end
            assign togv[8*j +: 8] = t;
        end
    endgenerate

    // Capture of DC_DATA / DC_ADDR / DC_CSn[1] on CS0-qualified WRn falls:
    // the first 8 after the arm; wcnt counts all of them (saturating).
    // dc index: 0..15 DATA, 16..18 ADDR, 19 CSn[0], 20 CSn[1], 22 WRn.
    wire wr_fall = c3[22] & ~c2[22];
    wire cs0 = ~c2[19];
    wire cap_hit = g_en & wr_fall & cs0;
    reg [3:0] cap_n;
    reg [15:0] wcnt;
    reg [31:0] oticks;
    always @(posedge ref_clk or posedge clr) begin
        if (clr) begin
            cap_n <= 4'd0;
            wcnt <= 16'd0;
            oticks <= 32'd0;
        end else begin
            if (g_en) oticks <= oticks + 1'b1;
            if (cap_hit) begin
                if (wcnt != 16'hFFFF) wcnt <= wcnt + 1'b1;
                if (!cap_n[3]) cap_n <= cap_n + 1'b1;
            end
        end
    end
    wire [127:0] capd;
    wire [31:0]  capa;
    genvar k;
    generate
        for (k = 0; k < 8; k = k + 1) begin : cp
            reg [15:0] d;
            reg [3:0]  a;
            always @(posedge ref_clk or posedge clr) begin
                if (clr) begin
                    d <= 16'd0;
                    a <= 4'd0;
                end else if (cap_hit && !cap_n[3] && cap_n[2:0] == k) begin
                    d <= c2[15:0];
                    a <= {c2[20], c2[18:16]};
                end
            end
            assign capd[16*k +: 16] = d;
            assign capa[4*k +: 4] = a;
        end
    endgenerate

    // ------------------------------------------------------- read mux --
    wire [143:0] rawp = {2'b00, raw};
    wire [143:0] s0p  = {2'b00, seen0};
    wire [143:0] s1p  = {2'b00, seen1};
    wire [271:0] togp = {8'h00, togv};
    wire [15:0] status = {4'h5, cap_n, 2'b00, g_en, win_done, win_run, arm_g, arm_w, clr};
    wire [3:0] lo = addr[3:0];
    wire [2:0] ci = addr[3:1];

    always @* begin
        d_out = {8'hA5, addr};  // unmapped: address echo
        case (addr[7:4])
            4'h0: case (lo)
                4'h0: d_out = 16'hC0DE;
                4'h3: d_out = 16'h3F21;
                4'h5: d_out = 16'h5CA1;
                4'h6: d_out = status;
                4'h7: d_out = WIN_LOG2;
                default: ;
            endcase
            4'h3: d_out = 16'h0001 << lo;             // walking 1
            4'h5: d_out = ~(16'h0001 << lo);          // walking 0
            4'h6: if (lo <= 4'd8) d_out = rawp[16*lo +: 16];
            4'h7: if (lo <= 4'd8) d_out = s0p[16*lo +: 16];
            4'h9: if (lo <= 4'd8) d_out = s1p[16*lo +: 16];
            4'hA: d_out = togp[16*lo +: 16];
            4'hB: if (lo == 4'd0) d_out = togp[256 +: 16];
            4'hC: d_out = addr[0] ? fcv[32*ci + 16 +: 16] : fcv[32*ci +: 16];
            4'hD: d_out = addr[0] ? {8'h00, wcv[24*ci + 16 +: 8]} : wcv[24*ci +: 16];
            4'hE: d_out = addr[0] ? {(cap_n > {1'b0, ci}), 11'd0, capa[4*ci +: 4]}
                                  : capd[16*ci +: 16];
            4'hF: case (lo)
                4'h0, 4'h1, 4'h2, 4'h3, 4'h4: d_out = status;
                4'h5: d_out = wcnt;
                4'h6: d_out = oticks[15:0];
                4'h7: d_out = oticks[31:16];
                default: ;
            endcase
            default: ;
        endcase
        // Address one-hot words (A1..A8 one at a time).
        case (addr)
            8'h01: d_out = 16'hB001;
            8'h02: d_out = 16'hB102;
            8'h04: d_out = 16'hB204;
            8'h08: d_out = 16'hB308;
            8'h10: d_out = 16'hB410;
            8'h20: d_out = 16'hB520;
            8'h40: d_out = 16'hB640;
            8'h80: d_out = 16'hB780;
            default: ;
        endcase
    end
endmodule
